#!/bin/bash

echo 'Cleaning up mem...' && sudo sync && echo 3 | sudo tee /proc/sys/vm/drop_caches && echo 'Downloading test model...' && mkdir -p models && source ~/.bashrc && hf download --local-dir models/txt --max-workers 14 unsloth/Qwen3-0.6B-GGUF Qwen3-0.6B-UD-Q8_K_XL.gguf && echo 'Model successfully downloaded!' && echo 'Testing llama-cli without Flash Attention' && ~/lcpp/base/base/bin/llama-cli --offline -lv 3 -fa off -s 1 --temp 0.01 -m ~/models/txt/Qwen3-0.6B-UD-Q8_K_XL.gguf --jinja -c 4096 -n 512 -sys "You are a professional writer that writes highly coherent huge books and encyclopedias, and that writes complete essays on user demand." -p "Explain (extensively) everything that scientists know that can/will happen in the future" && echo 'Testing llama-cli with Flash Attention enabled' && ~/lcpp/base/base/bin/llama-cli --offline -lv 3 -fa on -s 1 --temp 0.01 -m ~/models/txt/Qwen3-0.6B-UD-Q8_K_XL.gguf --jinja -ctk q8_0 -ctv q8_0 -c 0 -n 512 -sys "You are a professional writer that writes highly coherent huge books and encyclopedias, and that writes complete essays on user demand." -p "Explain (extensively) everything that scientists know that can/will happen in the future"
